CREATE TABLE regions(code varchar(6) PRIMARY KEY,name varchar(30) NOT NULL UNIQUE);
INSERT INTO regions(code,name) VALUES ('110000','北京'),('120000','天津'),('130000','河北'),('140000','山西'),('150000','内蒙古'),('210000','辽宁'),('220000','吉林'),('230000','黑龙江'),('310000','上海'),('320000','江苏'),('330000','浙江'),('340000','安徽'),('350000','福建'),('360000','江西'),('370000','山东'),('410000','河南'),('420000','湖北'),('430000','湖南'),('440000','广东'),('450000','广西'),('460000','海南'),('500000','重庆'),('510000','四川'),('520000','贵州'),('530000','云南'),('540000','西藏'),('610000','陕西'),('620000','甘肃'),('630000','青海'),('640000','宁夏'),('650000','新疆'),('710000','台湾'),('810000','香港'),('820000','澳门');
CREATE TABLE user_avatar(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,object_key text NOT NULL UNIQUE,content_type text NOT NULL CHECK(content_type IN ('image/jpeg','image/png','image/webp')),byte_size integer NOT NULL CHECK(byte_size>0 AND byte_size<=5242880),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX user_avatar_owner ON user_avatar(user_id);
CREATE TABLE user_profile(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,display_name varchar(24) NOT NULL DEFAULT '食库朋友' CHECK(char_length(btrim(display_name)) BETWEEN 2 AND 24),region_code varchar(6) REFERENCES regions(code),avatar_preset text NOT NULL DEFAULT 'tomato' CHECK(avatar_preset IN ('tomato','rice','cat','mushroom')),avatar_id uuid REFERENCES user_avatar(id) ON DELETE SET NULL,bio varchar(160) NOT NULL DEFAULT '',diet_goal text NOT NULL DEFAULT '均衡饮食' CHECK(diet_goal IN ('均衡饮食','控制热量','高蛋白','清淡少油')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO user_profile(user_id) SELECT id FROM users;
CREATE INDEX user_profile_region ON user_profile(region_code);
CREATE TABLE recipe_ingredient(recipe_id uuid NOT NULL REFERENCES recipe_catalog(id) ON DELETE CASCADE,position smallint NOT NULL CHECK(position>=0),name text NOT NULL CHECK(length(name)>0),quantity numeric NOT NULL CHECK(quantity>=0),unit varchar(20) NOT NULL,optional boolean NOT NULL DEFAULT false,amount_text text NOT NULL DEFAULT '',quantity_source text NOT NULL DEFAULT '',quantity_basis text NOT NULL DEFAULT '',PRIMARY KEY(recipe_id,position));
CREATE INDEX recipe_ingredient_lookup ON recipe_ingredient(name,recipe_id);
CREATE TABLE recipe_step(recipe_id uuid NOT NULL REFERENCES recipe_catalog(id) ON DELETE CASCADE,position smallint NOT NULL CHECK(position>=0),instruction text NOT NULL CHECK(length(instruction)>0),PRIMARY KEY(recipe_id,position));
CREATE TABLE recipe_diet_tag(recipe_id uuid NOT NULL REFERENCES recipe_catalog(id) ON DELETE CASCADE,tag text NOT NULL,PRIMARY KEY(recipe_id,tag));
CREATE INDEX recipe_diet_tag_lookup ON recipe_diet_tag(tag,recipe_id);
